/**
 * Evalúa una fórmula de hoja de cálculo almacenada como string, utilizando el estado actual.
 * Solo soporta SUMA(rango) y operaciones aritméticas básicas (-, *, /).
 * @param {string} formula - La cadena de la fórmula (ej: "=SUMA(A1:A3)"). Debe empezar con '='.
 * @returns {number|string} El resultado calculado o el valor original si es inválido.
 */
function calculateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula; // No es fórmula, lo devolvemos como está.
    }

    let expression = formula.substring(1).trim();
    let result;

    // 1. Manejo de SUMA (Función)
    const sumMatch = expression.match(/^SUMA\((.+)\)$/i);
    if (sumMatch) {
        const rangeOrListString = sumMatch[1];
        let valuesToSum = [];

        // Detectar si es un rango (A1:B2) o una lista separada por punto y coma (A1;B2;C3)
        if (rangeOrListString.includes(':')) {
            const rangeMatch = rangeOrListString.match(/([A-Z]+[0-9]+):?([A-Z]+[0-9]*)/);
            if (rangeMatch) {
                let startCol = rangeMatch[1].charCodeAt(0) - 'A'.charCodeAt(0);
                let startRow = parseInt(rangeMatch[1].substring(1));
                let endCol = rangeMatch[2].charCodeAt(0) - 'A'.charCodeAt(0);
                let endRow = parseInt(rangeMatch[2].substring(1));

                // Iterar sobre el rango (columna/fila) y sumar los valores
                for (let r = startRow; r <= endRow; r++) {
                    for (let c = Math.min(startCol, endCol); c <= Math.max(startCol, endCol); c++) {
                        const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
                        const cellId = `${colLetter}${r}`;
                        if (estado[cellId] !== undefined && !isNaN(parseFloat(estado[cellId]))) {
                             valuesToSum.push(parseFloat(estado[cellId]));
                        }
                    }
                }
            } else if (rangeOrListString.includes(';')) { // Manejo de lista con ; si falla el rango simple
                 const cells = rangeOrListString.split(';').map(s => s.trim());
                 cells.forEach(cellId => {
                     if (estado[cellId] !== undefined && !isNaN(parseFloat(estado[cellId]))) {
                         valuesToSum.push(parseFloat(estado[cellId]));
                     }
                 });
            }
        } else { // Manejo de lista separada por ; (A1;B2)
            const cells = rangeOrListString.split(';').map(s => s.trim());
            cells.forEach(cellId => {
                if (estado[cellId] !== undefined && !isNaN(parseFloat(estado[cellId]))) {
                    valuesToSum.push(parseFloat(estado[cellId]));
                }
            });
        }

        result = valuesToSum.reduce((sum, val) => sum + val, 0);
        return result.toString();
    }


    // 2. Manejo de operaciones aritméticas básicas (A1-B1, A1*B1, etc.)
    let match;
    // Intentar capturar patrones como =A1-B1 o =A1*(B2/C3)
    const arithmeticRegex = /^[a-zA-Z]+[0-9]+[\s\S]*$/;

    if (arithmeticRegex.test(expression)) {
        try {
            // Reemplazar referencias de celda por sus valores numéricos actuales en el estado.
            let processedExpression = expression;

            // Regex para capturar cualquier referencia al estilo A1, B2, etc.
            processedExpression = processedExpression.replace(/([A-Z]+[0-9]+)/g, (match) => {
                const cellId = match;
                const value = estado[cellId];
                // Si el valor es un número válido, lo retorna como string numérico para eval()
                if (value !== undefined && !isNaN(parseFloat(value))) {
                    return parseFloat(value);
                } 
                // Si no tiene valor o no es numérico, devolver '0' para evitar NaN en la evaluación.
                return 0;
            });

            // Evaluar la expresión matemática (PELIGROSO EN PRODUCCIÓN, pero necesario aquí por el scope)
            result = eval(processedExpression);

        } catch (e) {
            console.error("Error al evaluar fórmula aritmética:", e);
            return formula; // Falló la evaluación, devolver la fórmula original.
        }
    } else {
         // Si no coincide con ninguna lógica conocida, asumimos que es texto o una fórmula compleja no implementada.
        result = null; 
    }

    if (result === null) {
        return formula;
    }

    // Devolver el resultado formateado como string.
    return result.toString();
}
