### FUNCION: evaluateFormula
```javascript
/**
 * Evalúa una fórmula de estilo Excel en el estado actual, si la celda comienza con '='.
 * @param {string} cellId - El ID de la celda que contiene la fórmula (ej: "B4").
 * @param {string} formulaString - El valor literal de la celda (incluyendo '=SUMA(...)').
 * @returns {string} El resultado calculado o el texto original si no es una fórmula válida.
 */
function evaluateFormula(cellId, formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString; // No es una fórmula
    }

    let cleanFormula = formulaString.substring(1).trim(); 

    // --- Manejo de SUMA (Requisito R3) ---
    const sumMatch = cleanFormula.match(/^SUMA\((.*)\)$/i);
    if (sumMatch) {
        let content = sumMatch[1];
        let valuesToSum = [];

        // 1. Extraer referencias de rango (ej: A1:A3).
        const rangeMatches = [...content.matchAll(/([A-Z]+[0-9]+):?([A-Z]+[0-9]+)/g)];
        for (const match of rangeMatches) {
            let startId = match[1];
            let endId = match[2] || startId; // Si no hay ':' asumimos que es un solo ID

            // Determinar la columna y el rango de filas.
            const colLetter = startId.match(/[A-Z]+/)[0];
            const startRow = parseInt(startId.match(/\d+/)[0]);
            const endRow = (endId.match(/\d+/)? ? parseInt(endId.match(/\d+/)[0]) : startRow);

            for (let r = startRow; r <= endRow; r++) {
                valuesToSum.push(`${colLetter}${r}`);
            }
        }

        // 2. Extraer referencias discretas separadas por punto y coma o comas, si no fueron cubiertas por rangos.
        const discreteMatches = [...content.matchAll(/([A-Z]+[0-9]+)/g)];
        for (const match of discreteMatches) {
             let cellId = match[0];
             // Solo agregamos IDs que representan celdas y no fueron ya procesados en un rango de manera efectiva.
             if (!valuesToSum.includes(cellId)) {
                valuesToSum.push(cellId);
             }
        }

        let total = valuesToSum.reduce((acc, id) => {
            // Usamos parseFloat para tratar los valores como números en el estado.
            const value = parseFloat(estado[id] || 0);
            return acc + value;
        }, 0);

        // Retornar el resultado numérico formateado como string.
        return total.toString();
    }

    // --- Manejo de operaciones aritméticas simples (A1-B1, etc.) ---
    try {
        let expression = cleanFormula;
        // Reemplazar todas las referencias de celdas ([A-Z]+[0-9]+) con sus valores numéricos reales del estado.
        expression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
            const value = parseFloat(estado[match] || 0);
            // Si el valor es NaN o la celda no existe, lo tratamos como '0' para evitar fallos en eval().
            return isNaN(value) ? '0' : value; 
        });

        // Evaluar la expresión matemática resultante.
        let result = eval(expression);

        if (!isNaN(result)) {
             return result.toString();
