        // 2. Extraer referencias discretas separadas por punto y coma o comas, si no fueron cubiertas por rangos.
        const discreteMatches = [...content.matchAll(/([A-Z]+[0-9]+)/g)];
        for (const match of discreteMatches) {
             let cellId = match[0];
             if (!valuesToSum.includes(cellId)) {
                valuesToSum.push(cellId);
             }
        }

        let total = valuesToSum.reduce((acc, id) => {
            // Usamos parseFloat para tratar los valores como números en el estado.
            const value = parseFloat(estado[id] || 0);
            return acc + value;
        }, 0);

        // Retornar el resultado numérico formateado como string.
        return total.toString();
    }

    // --- Manejo de operaciones aritméticas simples (A1-B1, etc.) ---
    try {
        let expression = cleanFormula;
        // Reemplazar todas las referencias de celdas ([A-Z]+[0-9]+) con sus valores numéricos reales del estado.
        expression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
            const value = parseFloat(estado[match] || 0);
            return isNaN(value) ? '0' : value; 
