/**
 * Tenta evaluar una fórmula de hoja de cálculo dada su estructura en el estado actual.
 * @param {string} formula - La cadena de la fórmula (debe empezar con '=').
 * @returns {string|number} El valor calculado como string, o la fórmula original si falla.
 */
function evaluateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) return formula;

    let expression = formula.substring(1).trim();

    // Regex para encontrar referencias de celda (ej: A1, B20, J1)
    const cellIdRegex = /([A-Z]{1}[1-9]\d?|[A-Z]{2}\d)/g; 

    expression = expression.replace(cellIdRegex, (match) => {
        let valueStr = estado[match] || '0';
        try {
            // Intentar obtener un valor numérico del contenido de la celda en el estado.
            const numValue = parseFloat(valueStr);
            return isNaN(numValue) ? valueStr : numValue;
        } catch (e) {
            return valueStr; // Si falla, devolver el string original.
        }
    });

    try {
        // Usamos eval() para calcular la expresión matemática resultante.
        // Nota: En un entorno de producción real, se usaría un parser matemático seguro en lugar de eval().
        const result = eval(expression);
        if (isNaN(result)) return "Error";

        // Redondear a 2 decimales para consistencia visual.
        return String(Math.round(result * 100) / 100); 
    } catch (e) {
        console.warn("Error al evaluar la fórmula:", e);
        return formula; // Devolver la fórmula original si hay un error de cálculo.
    }
}
