function recalculateAllFormulas() {
    for (const cellId in estado) {
        if (!estado[cellId]) continue;

        let value = estado[cellId];

        // Solo intentar calcular si parece una fórmula y es un string.
        if (typeof value === 'string' && value.startsWith('=')) {
            const calculatedValue = evaluateFormula(value);

            // Actualizar el estado con el resultado calculado. 
            estado[cellId] = calculatedValue; 
        }
    }
}

