    // Esto se salta porque el DOM está predefinido y solo necesitamos actualizar contenido.

    // 2. Iterar sobre todas las celdas de datos (tbody > tr > td[data-cell])
    const cells = tableBody.querySelectorAll('td[data-cell]');

    cells.forEach(cellElement => {
        const cellId = cellElement.getAttribute('data-cell');
        // Obtener el valor del estado, si no existe por algún motivo (aunque debería existir), usar vacío.
        const valueFromState = estado[cellId] || ''; 

        // Actualizar el contenido visible de la celda.
        cellElement.textContent = valueFromState;

        // Asegurarse de que el atributo contenteditable esté presente para el manejo de eventos.
        cellElement.setAttribute('contenteditable', 'true');

        // Restaurar estilos de color si existen en el estado guardado (propiedad _color)
        const colorKey = `${cellId}_color`;
        if (estado[colorKey]) {
            cellElement.style.backgroundColor = estado[colorKey];
            cellElement.classList.add('colored-cell');
        } else {
             cellElement.style.backgroundColor = '';
             cellElement.classList.remove('colored-cell');
        }
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const tableBody = document.getElementById('spreadsheetTable');

    // Elemento para el menú contextual (Context Menu)
    let contextMenu = document.createElement('ul');
    contextMenu.className = 'context-menu';
    document.body.appendChild(contextMenu);

    /**
     * Manejador de eventos para celdas editables (blur o change). Captura el valor cuando el usuario termina de editar.
     */
    function handleCellChange(event) {
        const target = event.target;
        // 1. Identificar la celda por su atributo data-cell.
        const cellId = target.getAttribute('data-cell');
        if (!cellId) return;

        // 2. Obtener el nuevo valor del DOM.
        let newValue = target.textContent; 

        // 3. Lógica: Actualizar el estado con el valor finalizado (blur/change).
        setCellValue(cellId, newValue);

        // 4. Guardar y Renderizar para reflejar los cambios en toda la app.
        guardar();
        render();
    }

    /**
     * Manejador de eventos para clic derecho (Context Menu).
     */
    function handleRightClick(event) {
        const target = event.target;
        // 1. Prevenir el menú contextual nativo del navegador.
        event.preventDefault();

        // Verificar si se hizo clic en una celda de datos válida.
        const cellElement = target.closest('td[data-cell]');
        if (!cellElement) {
            contextMenu.style.display = 'none';
            return;
        }

        // 2. Posicionar y mostrar el menú contextual.
        contextMenu.style.top = `${event.clientY - contextMenu.offsetHeight / 2}px`;
        contextMenu.style.left = `${event.clientX}px`;
        contextMenu.style.display = 'block';

        // Limpiar contenido anterior y construir el nuevo menú.
        contextMenu.innerHTML = ''; // Limpiar
        const menuItems = [
            { text: "Cambiar color de fondo", action: () => handleColorAction(cellElement, event) }
        ];

        menuItems.forEach(item => {
            const li = document.createElement('li');
            li.innerHTML = `<span>${item.text}</span>`;
            // Agregar un botón o mecanismo para seleccionar el color (ejemplo: rojo).
            if (item.text.includes("color")) {
                 // Usamos el color primario de prueba como ejemplo visible en el menú
                const colorIndicator = document.createElement('button');
                colorIndicator.style.backgroundColor = '#FF0000'; 
                colorIndicator.title = "Ejemplo: Rojo";
                li.appendChild(colorIndicator);
            }

            li.onclick = () => {
                item.action();
                contextMenu.style.display = 'none'; // Ocultar al seleccionar una opción
            };
            contextMenu.appendChild(li);
        });
    }

    /**
     * Lógica que se ejecuta cuando el usuario selecciona "Cambiar color de fondo".
     */
    function handleColorAction(cellElement, event) {
        // Simular la selección del color #FF0000 (Rojo) como ejemplo. 
        const selectedColor = '#FF0000'; 
        applyBackgroundColor(cellElement, selectedColor);
        console.log(`Color aplicado a ${cellElement.getAttribute('data-cell')}: ${selectedColor}`);
    }


    // Event Listeners Globales:
    document.addEventListener('contextmenu', handleRightClick);

    // Para ocultar el menú cuando se hace clic en cualquier otro lugar
    document.addEventListener('click', (e) => {
        if (!e.target.closest('.context-menu')) {
            contextMenu.style.display = 'none';
        }
    });


    // Eventos de edición existentes:
    tableBody.addEventListener('blur', handleCellChange);
    tableBody.addEventListener('change', handleCellChange);
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
