```javascript
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
let estado = {};
const CLAVE = "app";
let selectedColumnLetter = null; // Nuevo estado para rastrear qué columna está seleccionada

/** Inicializa el estado con todas las 200 celdas (A1 a J20) y sus valores vacíos. */
function initializeEstado() {
    estado = {};
    for (let r = 1; r <= 20; r++) {
        for (let c = 0; c < 10; c++) {
            // Columna A=0, B=1, ..., J=9. Letra = 'A' + índice de columna.
            const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
            const cellId = `${colLetter}${r}`;
            estado[cellId] = '';
        }
    }
}

function cargar() { 
    // Siempre inicializar el estado para asegurar que todas las claves existan, incluso si no hay datos guardados.
    initializeEstado(); 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) {
            let loadedState = JSON.parse(s);
            // Fusionar el estado cargado con la estructura inicial para garantizar que las claves faltantes no rompan nada.
            estado = { ...estado, ...loadedState };
        }
    } catch (e) { 
        console.error("Error al cargar el estado:", e); 
    } 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) { 
        console.error("Error al guardar el estado:", e); 
    } 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el valor de una celda específica en el estado global.
 * @param {string} cellId - El identificador de la celda (ej: "A1").
 * @param {string} value - El nuevo contenido del texto.
 */
function setCellValue(cellId, value) {
    if (!estado[cellId]) {
        console.warn(`Intento de actualizar una celda no inicializada: ${cellId}`);
        return; // Prevenir errores si el ID es inválido.
    }
    // Almacenamos el valor limpio y estandarizado (string).
    estado[cellId] = String(value); 
}

/**
 * Selecciona una columna por su letra, actualizando el estado de la UI.
 * @param {string} letter - La letra de la columna (A-J).
 */
function selectColumn(letter) {
    selectedColumnLetter = letter;
    // Aquí no actualizamos 'estado', solo nuestro estado UI/lógico interno.
    console.log(`Columna ${letter} seleccionada.`);
}

/**
 * Limpia el contenido de todas las celdas en la columna dada.
 * @param {string} letter - La letra de la columna a limpiar.
 */
function clearColumn(letter) {
    for (let r = 1; r <= 20; r++) {
        const cellId = `${letter}${r}`;
        setCellValue(cellId, '');
    }
}

/**
 * Borra conceptualmente la columna y actualiza el estado.
 * NOTA: En esta implementación simple, 'borrar' significa limpiar los datos de esa columna sin modificar el DOM.
 * @param {string} letter - La letra de la columna a borrar/limpiar su contenido.
 */
function deleteColumn(letter) {
    // Para efectos prácticos en este modelo, borramos el contenido del estado.
    clearColumn(letter);
}

/**
 * Aplica un fondo específico a todas las celdas de la columna dada.
 * @param {string} letter - La letra de la columna (A-J).
 * @param {string} color - El color hexadecimal o nombre CSS.
 */
function setBackground(letter, color) {
    // Este cambio es puramente visual y solo afecta a render() para el estilo.
    // No necesitamos cambiar 'estado' ya que no guardamos estilos de fondo en los datos.
    console.log(`Aplicando fondo ${color} a la columna ${letter}.`);
    // Dejamos el estado intacto, pero pedimos un re-renderizado visual con el color aplicado.
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const tableBody = document.getElementById('spreadsheetTable');
    const columnHeaders = tableBody.querySelector('#spreadsheetTable thead tr');

    // Limpiar clases de selección anteriores en todos los elementos
    tableBody.querySelectorAll('td').forEach(cell => cell.classList.remove('selected-column'));
    columnHeaders.querySelectorAll('.column-header').forEach(th => th.classList.remove('selected-column'));


    // 1. Iterar sobre todas las celdas de datos (tbody > tr > td[data-cell])
    const cells = tableBody.querySelectorAll('td[data-cell]');

    cells.forEach(cellElement => {
        const cellId = cellElement.getAttribute('data-cell');
        // Obtener el valor del estado, si no existe por algún motivo (aunque debería existir), usar vacío.
        const valueFromState = estado[cellId] || ''; 

        // Actualizar el contenido visible de la celda.
        cellElement.textContent = valueFromState;

        // Asegurarse de que el atributo contenteditable esté presente para el manejo de eventos.
        cellElement.setAttribute('contenteditable', 'true');
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const tableBody = document.getElementById('spreadsheetTable');
    const headerRow = document.querySelector('#spreadsheetTable thead tr');
    const controlsContainer = document.getElementById('columnControls');

    // --- 1. Manejador de eventos para celdas editables (TD) ---
    /**
     * Captura el valor cuando el usuario termina de editar (blur o change).
     */
    function handleCellChange(event) {
        const target = event.target;
        // 1. Identificar la celda por su atributo data-cell.
        const cellId = target.getAttribute('data-cell');
        if (!cellId) return;

        // 2. Obtener el nuevo valor del DOM.
        let newValue = target.textContent; 

        // 3. Lógica: Actualizar el estado con el valor finalizado (blur/change).
        setCellValue(cellId, newValue);

        // 4. Guardar y Renderizar para reflejar los cambios en toda la app.
        guardar();
        render();
    }

    tableBody.addEventListener('blur', handleCellChange);
    tableBody.addEventListener('change', handleCellChange);


    // --- 2. Event Delegation para Column Headers (A-J) ---
    headerRow.addEventListener('click', function(e) {
        const target = e.target;
        if (!target.classList.contains('column-header')) return;

        const letter = target.getAttribute('data-column');
        selectColumn(letter);
        renderColumnSelectionUI(letter); // Actualiza la UI de selección
    });


    // --- 3. Event Handlers para Controles (Botones) ---
    document.getElementById('deleteColumnBtn').addEventListener('click', () => {
        if (selectedColumnLetter) {
            deleteColumn(selectedColumnLetter);
            guardar();
            render();
        }
    });

    document.getElementById('clearColumnBtn').addEventListener('click', () => {
        if (selectedColumnLetter) {
            clearColumn(selectedColumnLetter);
            guardar();
            render();
        }
    });

    document.getElementById('colorColumnBtn').addEventListener('click', () => {
         if (selectedColumnLetter) {
             // Aplicamos un color de ejemplo, pero el usuario podría elegirlo en una UI real.
             const defaultColor = '#f0f8ff'; // AliceBlue
             setBackground(selectedColumnLetter, defaultColor); 
             render();
        }
    });

}

/**
 * Actualiza la interfaz de selección y los botones de control basados en la columna seleccionada.
 * @param {string | null} letter - La letra actualmente seleccionada.
 */
function renderColumnSelectionUI(letter) {
    const controlsContainer = document.getElementById('columnControls');
    const selectedLetterDisplay = document.getElementById('selectedColumnLetter');
    const deleteBtn = document.getElementById('deleteColumnBtn');
    const clearBtn = document.getElementById('clearColumnBtn');
    const colorBtn = document.getElementById('colorColumnBtn');

    if (letter) {
        // 1. Actualizar display de selección
        selectedLetterDisplay.textContent = letter;

        // 2. Activar botones
        deleteBtn.style.display = 'inline-block';
        clearBtn.style.display = 'inline-block';
        colorBtn.style.display = 'inline-block';

        // 3. Aplicar clase de selección visual en el header y las celdas
        const selectedHeader = document.querySelector(`.column-header[data-column="${letter}"]`);
        if (selectedHeader) {
            selectedHeader.classList.add('selected-column');
        }

        // Aplicar la clase a todas las celdas de esta columna en el body para visualización
        const cellsToHighlight = document.querySelectorAll(`td[data-cell^="${letter}"]`);
         cellsToHighlight.forEach(cell => cell.classList.add('selected-column'));


    } else {
        // Desactivar y limpiar UI si no hay columna seleccionada
        selectedLetterDisplay.textContent = 'Ninguna';
        deleteBtn.style.display = 'none';
        clearBtn.style.display = 'none';
        colorBtn.style.display = 'none';

        // Limpiar clases visuales
         document.querySelectorAll('.column-header').forEach(th => th.classList.remove('selected-column'));
         document.querySelectorAll('td[data-cell]').forEach(cell => cell.classList.remove('selected-column'));
    }
}


// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { 
    cargar(); 
    conectar(); 
    render(); 
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
