```javascript
function deleteSelectedColumn() {
    const columnLetter = window._selectedColumn;
    if (!columnLetter) return;

    // 1. Confirmar la acción destructiva.
    if (!confirm(`¿Está seguro que desea eliminar la columna ${columnLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 2. Limpiar el estado: Remover todas las claves de esta columna del objeto estado.
    for (let r = 1; r <= 20; r++) {
        const cellId = `${columnLetter}${r}`;
        delete estado[cellId];
    }

    // 3. Eliminar los elementos DOM:
    // a) Eliminar las celdas de datos (TDs).
    document.querySelectorAll(`td[data-cell^="${columnLetter}"]`).forEach(td => {
        td.remove();
    });

    // b) Eliminar el encabezado de la columna (TH en thead).
    const headerCell = document.querySelector(`.column-header th:has(span[data-letter="${columnLetter}"])`);
    if (headerCell && headerCell.parentNode) {
        headerCell.parentNode.removeChild(headerCell);
    }

    // 4. Resetear el estado de selección y guardar/renderizar.
    window._selectedColumn = null;
    guardar();
    render(); // Redibujar para que la estructura DOM refleje los cambios.
    console.log(`Columna ${columnLetter} eliminada.`);
}
