function showContextMenu(x, y) {
    // Limpiar cualquier menú existente
    document.querySelectorAll('.context-menu').forEach(el => el.remove());

    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.style.position = 'fixed';
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;
    menu.style.backgroundColor = '#fff';
    menu.style.border = '1px solid #ccc';
    menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
    menu.innerHTML = `
        <div class="context-item action-clear" data-action="clear">Borrar Contenido</div>
        <div class="context-item action-color" data-action="color">Cambiar Fondo Color</div>
        <div class="context-item action-delete" data-action="delete">Eliminar Columna</div>
    `;

    document.body.appendChild(menu);

    // Manejador de clics en los elementos del menú contextual
    menu.querySelectorAll('.context-item').forEach(item => {
        item.addEventListener('click', function() {
            const action = this.getAttribute('data-action');
            let event; // Usamos 'event' para obtener coordenadas si es necesario, aunque aquí no lo es.

            if (action === 'clear') {
                clearSelectedColumn();
            } else if (action === 'color') {
                // Pedir el color al usuario o usar un valor por defecto/placeholder.
                // Para el propósito del test, asumiremos que se abre un prompt de color.
                const colorInput = prompt("Ingrese el código hexadecimal del color de fondo (ej: #ff0000):", "#ffff00"); 
                if (colorInput) {
                    colorSelectedColumn(colorInput);
                }
            } else if (action === 'delete') {
                deleteSelectedColumn();
            }
            menu.remove(); // Cerrar el menú después de la acción
        });
    });
