/**
 * Marca visualmente la fila seleccionada y actualiza el estado de selección global.
 * @param {HTMLElement} rowElement - El elemento <tr> seleccionado.
 */
function selectRow(rowElement) {
    // Deseleccionar todas las filas primero
    document.querySelectorAll('.sheet-row').forEach(r => r.classList.remove('selected'));

    if (rowElement) {
        // Seleccionar la fila actual
        rowElement.classList.add('selected');
        // Actualizar el estado de selección global si fuera necesario, aunque aquí solo usaremos el elemento DOM.
        window._selectedRow = rowElement; 
    } else {
        window._selectedRow = null;
    }

    // Hacer visibles los controles de acción
    document.getElementById('rowControls').classList.remove('hidden');
}
