### FUNCION: handleRowAction
```js
/**
 * Maneja la ejecución de acciones sobre la fila seleccionada (borrar, limpiar contenido, color).
 * @param {string} action - La acción a realizar ('delete', 'clear_content', 'highlight_row').
 */
function handleRowAction(action) {
    const selectedRow = window._selectedRow;
    if (!selectedRow) return;

    // 1. Borrar Fila (Eliminar del DOM y el estado)
    if (action === 'delete') {
        const rowIndex = parseInt(selectedRow.dataset.rowIndex);

        // Limpiar todos los datos de la fila en el estado global antes de eliminarla.
        for (let c = 0; c < 10; c++) {
            const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
            const cellId = `${colLetter}${rowIndex}`;
            delete estado[cellId]; // Borrar del objeto de estado.
        }

        // Eliminar la fila física del DOM.
        selectedRow.remove();

        // Actualizar el contenedor y re-renderizar para limpiar cualquier clase o estado residual.
        guardar();
        render(); 
        selectRow(null); // Deseleccionar después de borrar.
    } 
    // 2. Limpiar Contenido
    else if (action === 'clear_content') {
        const rowIndex = parseInt(selectedRow.dataset.rowIndex);
        clearRowContent(rowIndex);
    }
    // 3. Cambiar Color Fondo
    else if (action === 'highlight_row') {
        applyRowColor(selectedRow);
    }
}
