/**
 * Aplica un color de fondo a todas las celdas de una fila dada.
 * @param {HTMLElement} rowElement - El elemento <tr> con la fila completa.
 */
function applyRowColor(rowElement) {
    // Seleccionar todas las celdas (<td> o <th> con data-cell) dentro de esta fila, excluyendo el label de la fila.
    const cells = Array.from(rowElement.querySelectorAll('td[data-cell], th[data-cell]');).map(cell => {
        // Aplicar estilo directamente al elemento DOM.
        cell.style.backgroundColor = '#fff3cd'; // Color amarillo suave para resaltar.
        return cell;
    });

    // Nota: No es necesario redibujar o guardar el estado ya que solo afecta la presentación visual temporalmente.
}
