        const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
        const cellId = `${colLetter}${rowNumber}`;
        const cellElement = document.querySelector(`td[data-cell="${cellId}"]`);
        if (cellElement) {
            cellElement.style.display = 'none';
        }
    }

     // 3. Ocultar la fila completa y actualizar el estado visual globalmente.
    document.getElementById('spreadsheetTable').setAttribute('data-hidden-rows', (document.getAttribute('data-hidden-rows') || '') + ',${rowNumber}');
    render();
}
```

### FUNCION: showRow
```js
function showRow(rowNumber) {
    // 1. Mostrar la etiqueta de fila (el número en el th).
    const rowLabel = document.querySelector(`.row-label[data-row="${rowNumber}"]`);
    if (!rowLabel) return;

    rowLabel.style.display = ''; // Restablecer display

    // 2. Mostrar las celdas completas de la fila.
    for (let c = 0; c < 10; c++) {
        const colLetter = String.fromCharCode('A'.charCodeAt(0) + c);
        const cellId = `${colLetter}${rowNumber}`;
        const cellElement = document.querySelector(`td[data-cell="${cellId}"]`);
        if (cellElement) {
            cellElement.style.display = ''; // Restablecer display
        }
    }

     // 3. Limpiar el atributo de filas ocultas y redibujar.
    const hiddenRowsAttr = document.getElementById('spreadsheetTable').getAttribute('data-hidden-rows');
    if (hiddenRowsAttr && hiddenRowsAttr.includes(rowNumber)) {
        document.getElementById('spreadsheetTable').removeAttribute('data-hidden-rows');
    }

    render();
}
